#include "md_knn.h"

void md_kernel(
    TYPE force_x[nAtoms],
    TYPE force_y[nAtoms],
    TYPE force_z[nAtoms],
    TYPE position_x[nAtoms],
    TYPE position_y[nAtoms],
    TYPE position_z[nAtoms],
    int32_t NL[nAtoms * maxNeighbors])
{
    int i, j, k;
    TYPE delx, dely, delz;
    TYPE r2inv, r6inv, frc;
    TYPE fx, fy, fz;

    for (i = 0; i < nAtoms; i++) {
        fx = force_x[i];
        fy = force_y[i];
        fz = force_z[i];

        for (j = 0; j < maxNeighbors; j++) {
            k = NL[i * maxNeighbors + j];

            delx = position_x[i] - position_x[k];
            dely = position_y[i] - position_y[k];
            delz = position_z[i] - position_z[k];

            r2inv = 1.0 / (delx * delx + dely * dely + delz * delz);
            r6inv = r2inv * r2inv * r2inv;
            frc = r2inv * r6inv * (lj1 * r6inv - lj2);

            fx += delx * frc;
            fy += dely * frc;
            fz += delz * frc;
        }

        force_x[i] = fx;
        force_y[i] = fy;
        force_z[i] = fz;
    }
}
